const input = $input.first().json;
const execution = input?.execution ?? {};
const workflow = input?.workflow ?? {};
const error = execution?.error ?? input?.error ?? {};

// `error.message` is n8n's OWN wording for the status code, never the vendor's. Every OpenAI 429
// reads "The service is receiving too many requests from you" whether we are genuinely rate-limited
// or simply out of credits — two failures with opposite fixes, one indistinguishable alert.
// The vendor's sentence lives in `description`; its machine-readable code survives only in the raw
// `messages[]` entry, shaped `429 - "{ \"error\": { \"message\", \"type\", \"code\" } }"`.
// Deliberately NOT read: `error.context.request` (the whole request body — prompts and lead PII) and
// `error.node` (node parameters). Neither belongs in Slack or in a durable row.
const clean = (value) => String(value).replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();

/** `429 - "{…}"` → the parsed body. n8n double-encodes it, hence the second parse. */
function parseVendorBody(text) {
  let candidate = String(text).replace(/^\s*\d{3}\s*-\s*/, '').trim();
  for (let attempt = 0; attempt < 2; attempt += 1) {
    let parsed;
    try {
      parsed = JSON.parse(candidate);
    } catch (e) {
      return null;
    }
    if (typeof parsed === 'string') { candidate = parsed; continue; }
    return parsed && typeof parsed === 'object' ? parsed : null;
  }
  return null;
}

let httpCode = error?.httpCode != null ? String(error.httpCode) : '';
let detail = error?.description ? clean(error.description) : '';
let vendorType = '';
let vendorCode = '';

for (const raw of Array.isArray(error?.messages) ? error.messages : []) {
  const text = String(raw);
  if (!httpCode) httpCode = (text.match(/^\s*(\d{3})\s*-/) ?? [])[1] ?? '';
  const body = parseVendorBody(text);
  const vendor = (body && typeof body.error === 'object' && body.error) || body;
  if (vendor && typeof vendor === 'object') {
    if (!vendorType && vendor.type) vendorType = clean(vendor.type);
    if (!vendorCode && vendor.code) vendorCode = clean(vendor.code);
    if (!detail && vendor.message) detail = clean(vendor.message);
  } else if (!detail) {
    detail = clean(text);
  }
}

// Postgres, Google and other non-HTTP nodes hang the real cause off `cause` instead.
if (!detail) detail = clean(error?.cause?.error?.message ?? error?.cause?.message ?? '');

const message = String(error?.message ?? input?.message ?? 'Unknown workflow failure');

// A detail identical to the generic message adds a line and no information. The cap is not
// cosmetic: a Postgres failure puts the ENTIRE failed statement in `description`, which would push
// hundreds of rows of client data into an ops channel. 500 chars keeps the cause readable; the full
// text stays one click away behind the execution URL.
const capped = detail.length > 500 ? detail.slice(0, 500) + '…' : detail;
const errorDetail = detail && detail !== message ? capped : '';

// The vendor often repeats the status code as its own `type` or `code`. "HTTP 500 · 500" is noise.
const errorCodes = [
  httpCode ? 'HTTP ' + httpCode : '',
  vendorType && vendorType !== httpCode ? vendorType : '',
  vendorCode && vendorCode !== httpCode && vendorCode !== vendorType ? vendorCode : '',
].filter(Boolean).join(' · ');

return [{ json: {
  workflow_name: String(workflow?.name ?? input?.workflowName ?? 'unknown workflow'),
  last_node: String(execution?.lastNodeExecuted ?? ''),
  error_message: message,
  error_detail: errorDetail,
  error_codes: errorCodes,
  execution_url: String(execution?.url || (execution?.id ? 'id ' + execution.id : 'no id')),
} }];
